import { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';

// Card หนังสือ: ใช้รูปปกจริงถ้า URL โหลดได้ ถ้า URL เสียให้ใช้ปกสำรองในเครื่อง
function BookCard({ book }) {
  const [coverFailed, setCoverFailed] = useState(false);
  const price = book.priceTHB
    ? `฿${book.priceTHB.toLocaleString('th-TH')}`
    : null;

  // รีเซ็ตสถานะเมื่อเปลี่ยนหนังสือหรือ URL ปก
  useEffect(() => {
    setCoverFailed(false);
  }, [book.id, book.coverUrl]);

  const coverSrc = book.coverUrl && !coverFailed
    ? book.coverUrl
    : '/book-cover-placeholder.svg';

  return (
    <Link
      to={`/books/${book.id}`}
      className="group block overflow-hidden rounded-xl border border-amber-100 bg-white transition hover:border-amber-300 hover:shadow-md"
    >
      <img
        src={coverSrc}
        alt={`ปกหนังสือ ${book.title}`}
        loading="lazy"
        onError={() => setCoverFailed(true)}
        className="aspect-[2/3] w-full object-cover"
      />
      <div className="p-3">
        <h3 className="truncate font-medium text-slate-900 text-sm" title={book.title}>
          {book.title}
        </h3>
        <p className="truncate text-xs text-slate-500 mt-0.5">{book.author}</p>
        <div className="mt-1 flex items-center justify-between">
          {book.category && (
            <span className="rounded-full bg-amber-50 px-2 py-0.5 text-xs text-amber-700">
              {book.category}
            </span>
          )}
          {price && <span className="text-xs font-medium text-slate-700">{price}</span>}
        </div>
      </div>
    </Link>
  );
}

export default BookCard;
